/* All play and progress stay on this device. No account or payment required. */
(()=>{
'use strict';
const $=s=>document.querySelector(s), app=$('#app'), G=Breakfast, themes=CATALOG;
const KEY='butce-duellosu-v2';
const homeIds=new Set(['yatak','oturma','salon','mutfak','banyo','oyunodasi','bahce','sinema','cocuk','dekor']);
const businessIds=new Set(['isyeri','kafe','restoran','magaza','otel','okul']);
let settings={mode:'cpu',order:'random',theme:'kahvalti'},session=null,bid=0,filter='Tümü',query='',sound=false,audio=null,installEvent=null;
try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored?.settings)settings={...settings,...stored.settings};if(stored?.session&&validSession(stored.session))session=stored.session;sound=stored?.sound===true;}catch{}
if(!themes.some(t=>t.id===settings.theme))settings.theme=themes[0].id;
if(!['cpu','local'].includes(settings.mode))settings.mode='cpu';if(!['random','ordered'].includes(settings.order))settings.order='random';
function validSession(s){try{return s.game.version===2&&themes.some(t=>t.id===s.game.themeId)&&['cpu','local'].includes(s.game.mode)&&s.game.players.length===2&&s.game.players.every(p=>Number.isInteger(p.money)&&p.money>=0&&p.money<=20&&Array.isArray(p.items))&&s.game.deck.length===10&&s.game.round>=0&&s.game.round<=10&&Array.isArray(s.queue)&&s.queue.every(id=>themes.some(t=>t.id===id))&&s.index>=0&&s.index<s.queue.length&&Array.isArray(s.results)&&['bid','handoff','reveal','finished'].includes(s.game.stage);}catch{return false;}}
function save(){try{localStorage.setItem(KEY,JSON.stringify({settings,session,sound}));}catch{}}
function theme(){return themes.find(t=>t.id===session.game.themeId);}
function name(i){return i===0?'Oyuncu 1':(session?.game.mode==='local'?'Oyuncu 2':'Bilgisayar');}
function tone(win=false){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const start=audio.currentTime;[win?523:390,win?659:510,win?784:620].forEach((f,i)=>{const o=audio.createOscillator(),v=audio.createGain();o.type='sine';o.frequency.value=f;v.gain.setValueAtTime(0,start+i*.09);v.gain.linearRampToValueAtTime(.07,start+i*.09+.01);v.gain.exponentialRampToValueAtTime(.001,start+i*.09+.14);o.connect(v);v.connect(audio.destination);o.start(start+i*.09);o.stop(start+i*.09+.15);});}catch{}}
function announce(t){$('#announcement').textContent=t;}
function scrollTop(){window.scrollTo({top:0,behavior:'instant'});}
function menu(){
 app.innerHTML=`<section class="menu-hero"><div><span class="eyebrow">20 TL İLE NE KADARINI KURABİLİRSİN?</span><h1>Küçük bütçe.<br><em>Büyük düello.</em></h1><p class="intro-copy">Hayalindeki odayı döşe, bir stadyum kur ya da en iyi kombini yap. Teklifini gizle, rakibini geç, koleksiyonunu tamamla.</p><div class="chips"><span class="chip">${themes.length} farklı kategori</span><span class="chip">Her kategoride 10 tur</span><span class="chip">Çevrimdışı oynanır</span></div></div><div class="world-art" aria-hidden="true"><div class="orbit-caption">SENİN DÜNYAN, SENİN SEÇİMİN.</div><div class="world-card wc1"><span>🛋️</span>Rüya odan</div><div class="world-card wc2"><span>🦁</span>Vahşi dünyan</div><div class="world-card wc3"><span>🖥️</span>Süper sistemin</div><div class="world-card wc4"><span>👗</span>Kendi stilin</div><div class="coin">20<small>TL</small></div></div></section>
 <section class="setup" aria-label="Oyun ayarları"><div><span class="setup-label">01 / RAKİBİNİ SEÇ</span><div class="segmented" id="mode-options"><button data-mode="cpu" class="${settings.mode==='cpu'?'active':''}" aria-pressed="${settings.mode==='cpu'}">🤖 Bilgisayara karşı</button><button data-mode="local" class="${settings.mode==='local'?'active':''}" aria-pressed="${settings.mode==='local'}">👥 2 kişi · aynı cihaz</button></div></div><div><span class="setup-label">02 / KATEGORİ AKIŞI</span><div class="segmented" id="order-options"><button data-order="random" class="${settings.order==='random'?'active':''}" aria-pressed="${settings.order==='random'}">⤨ Rastgele</button><button data-order="ordered" class="${settings.order==='ordered'?'active':''}" aria-pressed="${settings.order==='ordered'}">☷ Sıra sıra</button></div></div></section>
 ${session?`<div class="resume-banner"><div><b>Kaldığın yerden devam et</b><span>${themes.find(t=>t.id===session.game.themeId).name} · ${session.game.stage==='finished'?'Kategori tamamlandı':`Tur ${session.game.round+1}/10`}</span></div><button class="secondary" id="resume">Devam et →</button></div>`:''}
 <section class="category-section"><div class="category-heading"><div><span class="eyebrow">HER KATEGORİ, YENİ BİR MEYDAN OKUMA</span><h2>Hangi dünyayı kuruyoruz?</h2></div><label class="search"><span aria-hidden="true">⌕</span><input type="search" id="category-search" placeholder="Kategori ara…" aria-label="Kategori ara" autocomplete="off"></label></div><div class="filters" role="group" aria-label="Kategori grupları">${['Tümü','Ev ve yaşam','İş ve mekan','Stil','Macera ve eğlence'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><div class="category-grid" id="categories"></div></section>
 <div class="launch-bar"><div><span class="setup-label">İLK KATEGORİN</span><strong id="selected-label"></strong><small id="flow-note"></small></div><button class="primary" id="start">Düelloyu başlat <span>↗</span></button></div><p class="rules-note">Her oyuncuya 20 TL · Gizli teklifler · En yüksek teklif alır · Gerçek para kullanılmaz</p>`;
 renderCategories();
 $('#mode-options').onclick=e=>{const b=e.target.closest('[data-mode]');if(b){settings.mode=b.dataset.mode;save();menu();}};
 $('#order-options').onclick=e=>{const b=e.target.closest('[data-order]');if(b){settings.order=b.dataset.order;save();menu();}};
 $('.filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>{n.classList.toggle('active',n.dataset.filter===filter);n.setAttribute('aria-pressed',String(n.dataset.filter===filter));});renderCategories();}};
 $('#category-search').value=query;$('#category-search').oninput=e=>{query=e.target.value;renderCategories();};
 $('#categories').onclick=e=>{const b=e.target.closest('[data-theme]');if(b){settings.theme=b.dataset.theme;save();renderCategories();}};
 $('#start').onclick=()=>{if(session&&session.game.stage!=='finished'){confirmNew();return;}start();};
 if($('#resume'))$('#resume').onclick=()=>{bid=0;renderGame();scrollTop();};
}
function renderCategories(){const q=query.toLocaleLowerCase('tr');const list=themes.filter(t=>{let match=filter==='Tümü'||(filter==='Ev ve yaşam'&&homeIds.has(t.id))||(filter==='İş ve mekan'&&businessIds.has(t.id))||(filter==='Stil'&&['giydirme','taki'].includes(t.id))||(filter==='Macera ve eğlence'&&!homeIds.has(t.id)&&!businessIds.has(t.id)&&!['giydirme','taki'].includes(t.id));return match&&(t.name+' '+t.description).toLocaleLowerCase('tr').includes(q);});$('#categories').innerHTML=list.length?list.map(t=>`<button class="category-card ${settings.theme===t.id?'selected':''}" data-theme="${t.id}" aria-pressed="${settings.theme===t.id}"><span class="category-emoji" aria-hidden="true">${t.emoji}</span><span class="checkmark">${settings.theme===t.id?'✓':'↗'}</span><b>${t.name}</b><small>${t.description}</small><span class="category-meta">10 ürün <i>•</i> ${t.metric}</span></button>`).join(''):'<p class="empty-search">Bu isimde kategori yok. Başka bir kelime dene.</p>';const chosen=themes.find(t=>t.id===settings.theme);$('#selected-label').textContent=chosen.emoji+' '+chosen.name;$('#flow-note').textContent=settings.order==='random'?'Sonraki kategoriler karışık, tekrar etmeden.':'Bu kategoriden başlayıp listedeki sırayla.';}
function confirmNew(){const d=document.createElement('dialog');d.innerHTML='<button class="close" aria-label="Kapat">×</button><h2>Yeni bir düello?</h2><p>Devam eden oyunun yerini yeni oyun alacak.</p><button class="primary wide" id="new-yes">Yeni oyuna başla →</button><button class="secondary wide" style="margin-top:10px" id="new-no">Kaldığım oyunu koru</button>';document.body.append(d);d.querySelector('.close').onclick=()=>d.close();d.querySelector('#new-no').onclick=()=>d.close();d.querySelector('#new-yes').onclick=()=>{d.close();start();};d.onclose=()=>d.remove();d.showModal();}
function shuffled(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function start(){const id=settings.theme;const ids=themes.map(t=>t.id),idx=ids.indexOf(id);const queue=settings.order==='random'?[id,...shuffled(ids.filter(x=>x!==id))]:[...ids.slice(idx),...ids.slice(0,idx)];session={queue,index:0,order:settings.order,results:[],game:G.createGame(settings.mode,Math.random,themes.find(t=>t.id===id))};prepareRound();tone();renderGame();scrollTop();}
function prepareRound(){bid=0;session.game.turn=0;session.game.stage='bid';if(session.game.mode==='cpu')session.game.bids[1]=G.cpuBid(session.game);save();}
function playerCard(p,i,final=false){const s=G.score(p);return `<section class="player ${i===1?'rival':''}" aria-label="${name(i)} koleksiyonu"><div class="player-head"><b>${name(i)}</b><span class="avatar" aria-hidden="true">${i===0?'😎':(session.game.mode==='cpu'?'🤖':'✌️')}</span></div><div class="wallet"><small>Kalan bütçe</small><div class="money">${p.money} <span>TL</span></div></div><div class="table" data-theme-surface="${theme().id}">${p.items.length?p.items.map(x=>`<span class="mini-plate" role="img" aria-label="${x.name}, ${x.points} puan" title="${x.name} · ${x.points} puan">${x.emoji}</span>`).join(''):'<div class="empty-table">Burası şimdilik boş.<br>İlk parçanı kap!</div>'}</div><div class="player-foot"><span>${p.items.length} parça</span><strong>${s.total} puan</strong></div>${final?`<div class="score-detail">Ürünler: ${s.base} puan<br>Çeşitlilik: +${s.variety} puan<br>${new Set(p.items.map(x=>x.category)).size} farklı ürün grubu</div>`:''}</section>`;}
function renderGame(){const g=session.game;if(g.stage==='finished'){finish();return;}const t=theme(),item=g.deck[g.round];app.innerHTML=`<div class="game-top"><div><span class="eyebrow">${t.emoji} ${t.name.toLocaleUpperCase('tr')}</span><div class="round">TUR ${g.round+1} / ${g.deck.length}<div class="dots" aria-hidden="true">${g.deck.map((_,i)=>`<span class="dot ${i<g.round?'done':i===g.round?'current':''}"></span>`).join('')}</div></div></div><button class="secondary" id="back-menu">Menü ↗</button></div><div class="arena">${playerCard(g.players[0],0)}<section class="auction" id="auction" aria-label="Açık artırma"></section>${playerCard(g.players[1],1)}</div><div class="status-bar"><span aria-hidden="true">💡</span><p>${g.stage==='reveal'?'Yalnızca kazananın bütçesi azalır. Bir sonraki parça için stratejini kur.':`En yüksek teklif alır. Eşit teklifte bu turun önceliği: <strong>${name(g.round%2)}</strong>. İki pas = ürün alınmaz.`}</p></div><p class="rules-note">${session.index+1}. kategori / ${themes.length} · ${session.order==='random'?'Rastgele kategori akışı':'Sıralı kategori akışı'} · Her farklı ürün grubu +2 puan</p>${historyHTML()}`;
 $('#back-menu').onclick=()=>{save();menu();scrollTop();};
 const a=$('#auction');
 if(g.stage==='handoff'){a.innerHTML=`<div class="handoff"><span class="big-icon" aria-hidden="true">🤫</span><span class="eyebrow">TEKLİF GİZLENDİ</span><h2>Telefonu ${name(g.turn)}’e ver.</h2><p class="muted">Diğer oyuncu ekrana bakmasın.<br>Hazır olduğunda teklifini seç.</p><button class="primary" id="ready">Ben ${name(g.turn)}, hazırım →</button></div>`;$('#ready').onclick=()=>{g.stage='bid';bid=0;save();renderGame();};return;}
 a.innerHTML=`<span class="tag">${g.stage==='reveal'?'TEKLİFLER AÇILDI':'ŞİMDİ AÇIK ARTIRMADA'}</span><div class="dish" role="img" aria-label="${item.name}">${item.emoji}</div><h2>${item.name}</h2><div class="point-label">${item.category} <span>•</span> <b>${item.points} puan</b></div><div id="bid-area"></div>`;
 if(g.stage==='reveal'){const r=g.history[g.history.length-1];$('#bid-area').innerHTML=`<div class="result-bids"><div>${name(0)}<b>${r.bids[0]===0?'Pas':r.bids[0]+' TL'}</b></div><div>${name(1)}<b>${r.bids[1]===0?'Pas':r.bids[1]+' TL'}</b></div></div><p class="win-label">${r.winner===null?'İkiniz de pas geçtiniz.':name(r.winner)+' aldı! '+(r.tie?'(eşitlik önceliği)':'')}</p><button class="primary" id="next-round">${g.round===9?'Sonuçları gör':'Sonraki ürün'} →</button>`;$('#next-round').onclick=()=>{G.nextRound(g);if(g.stage!=='finished')prepareRound();else save();renderGame();};return;}
 const money=g.players[g.turn].money;bid=Math.min(bid,money);$('#bid-area').innerHTML=`<label class="bid-label" for="bid-range">${name(g.turn)}, gizli teklifin?</label><div class="stepper"><button id="decrease" aria-label="Teklifi 1 TL azalt">−</button><div class="bid-number"><span id="bid-value">${bid}</span> <small>TL</small></div><button id="increase" aria-label="Teklifi 1 TL artır">+</button></div><input type="range" id="bid-range" min="0" max="${money}" step="1" value="${bid}" aria-label="Gizli teklif, TL"><div class="bid-shortcuts"><button data-bid="0">Pas</button><button data-bid="${Math.min(1,money)}">1 TL</button><button data-bid="${Math.min(3,money)}">${Math.min(3,money)} TL</button><button data-bid="${money}">Tümü (${money} TL)</button></div><button class="primary" id="confirm-bid"></button><p class="turn-note">${money===0?'Bütçen bitti. Bu tur pas geçebilirsin.':g.mode==='local'?'Teklifin onaylanınca gizlenir, telefon diğer oyuncuya geçer.':'Bilgisayar teklifini önceden belirledi; seninkini göremez.'}</p>`;
 function update(){bid=Math.max(0,Math.min(money,bid));$('#bid-range').value=bid;$('#bid-value').textContent=bid;$('#confirm-bid').textContent=bid===0?'Bu tur pas geç →':`${bid} TL teklif ver →`;$('#decrease').disabled=bid===0;$('#increase').disabled=bid===money;}
 $('#decrease').onclick=()=>{bid--;update();};$('#increase').onclick=()=>{bid++;update();};$('#bid-range').oninput=e=>{bid=Number(e.target.value);update();};document.querySelectorAll('[data-bid]').forEach(b=>b.onclick=()=>{bid=Number(b.dataset.bid);update();});
 $('#confirm-bid').onclick=()=>{g.bids[g.turn]=bid;if(g.mode==='local'&&g.turn===0){g.turn=1;g.stage='handoff';bid=0;save();renderGame();announce('Teklif gizlendi. Telefonu Oyuncu 2’ye ver.');}else{const r=G.resolveRound(g,g.bids);tone(r.winner===0);save();renderGame();announce(r.winner===null?'İki oyuncu da pas geçti.':`${name(r.winner)} ${r.item.name} ürününü ${r.bids[r.winner]} TL’ye aldı.`);}};update();
}
function historyHTML(){const hist=session.game.history;if(!hist.length)return '';return `<details class="history"><summary>Geçmiş turlar (${hist.length})</summary><div class="history-row"><b>Ürün</b><b>Teklifler (1 / 2)</b><b>Kazanan</b></div>${hist.map(r=>`<div class="history-row"><span>${r.item.emoji} ${r.item.name}</span><span>${r.bids[0]} / ${r.bids[1]} TL</span><span>${r.winner===null?'İki pas':name(r.winner)}</span></div>`).join('')}</details>`;}
function finish(){const g=session.game,w=G.winner(g),t=theme();if(!g.recorded){session.results.push({theme:t.id,winner:w});g.recorded=true;save();tone(true);}const wins=[0,1].map(i=>session.results.filter(r=>r.winner===i).length),end=session.index+1>=session.queue.length;const next=end?null:themes.find(t=>t.id===session.queue[session.index+1]);app.innerHTML=`<section class="summary"><span class="eyebrow">${t.emoji} ${t.name.toLocaleUpperCase('tr')} · SONUÇLAR</span><h1>${w===null?'Denk bir düello!':`${name(w)}<br><em>kazandı!</em>`}</h1><p class="muted">${w===null?'Puanlar ve kalan bütçeler eşit.':G.score(g.players[0]).total===G.score(g.players[1]).total?'Puanlar eşit; kalan bütçe sonucu belirledi.':'İyi teklifler, güzel bir koleksiyon.'}</p><div class="series-score"><span>Seri skoru</span><b>${name(0)} ${wins[0]} <i>—</i> ${wins[1]} ${name(1)}</b><small>${session.results.length} kategori oynandı</small></div><div class="summary-players">${g.players.map((p,i)=>playerCard(p,i,true)).join('')}</div><div class="actions"><button class="primary" id="next-category">${end?'Tüm kategoriler tamamlandı! Yeni seri ↗':`Sonraki kategori: ${next.emoji} ${next.name} →`}</button><button class="secondary" id="finish-menu">Kategorileri seç</button></div><p class="micro">${end?'Harika bir seri!':`Yeni kategoride bütçeler tekrar 20 TL olur. ${session.order==='random'?'Kategoriler tekrar etmeden karışık gelir.':'Menüdeki sıra takip edilir.'}`}</p>${historyHTML()}</section>`;$('#finish-menu').onclick=()=>{menu();scrollTop();};$('#next-category').onclick=()=>{if(end){session=null;save();menu();scrollTop();return;}session.index++;const nextTheme=themes.find(t=>t.id===session.queue[session.index]);session.game=G.createGame(g.mode,Math.random,nextTheme);prepareRound();renderGame();scrollTop();};}
document.querySelector('.brand').onclick=e=>{e.preventDefault();menu();scrollTop();};
$('#help').onclick=()=>$('#help-dialog').showModal();$('#install-help').onclick=()=>$('#install-dialog').showModal();document.querySelectorAll('dialog').forEach(d=>{d.querySelectorAll('.close,.close-action').forEach(b=>b.onclick=()=>d.close());d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}};});
function updateSound(){$('#sound-state').textContent=sound?'açık':'kapalı';$('#sound').setAttribute('aria-label',sound?'Sesi kapat':'Sesi aç');$('#sound').title=sound?'Sesi kapat':'Sesi aç';}$('#sound').onclick=()=>{sound=!sound;updateSound();save();tone();};updateSound();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(installEvent){await installEvent.prompt();installEvent=null;$('#install').hidden=true;}else $('#install-dialog').showModal();};window.addEventListener('appinstalled',()=>{$('#install').hidden=true;installEvent=null;});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
menu();
})();
